{"path": "react.py", "content": "class InputCell:
    def __init__(self, initial_value):
        self._value = initial_value
        self._dependents = []

    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, new_value):
        if new_value == self._value:
            return
        self._value = new_value
        # Collect all downstream compute cells in topological order.
        order = []
        seen = set()

        def visit(cell):
            for dep in cell._dependents:
                if id(dep) not in seen:
                    seen.add(id(dep))
                    visit(dep)
                    order.append(dep)

        visit(self)
        order.reverse()
        old = {id(c): c._value for c in order}
        for cell in order:
            cell._recompute()
        for cell in order:
            if cell._value != old[id(cell)]:
                for cb in list(cell._callbacks):
                    cb(cell._value)


class ComputeCell(InputCell):
    def __init__(self, inputs, compute_function):
        self._inputs = list(inputs)
        self._function = compute_function
        self._dependents = []
        self._callbacks = []
        for cell in self._inputs:
            cell._dependents.append(self)
        self._recompute()

    @property
    def value(self):
        return self._value

    def _recompute(self):
        self._value = self._function([c.value for c in self._inputs])

    def add_callback(self, callback):
        self._callbacks.append(callback)

    def remove_callback(self, callback):
        if callback in self._callbacks:
            self._callbacks.remove(callback)
